import React, { useEffect, useState } from 'react';
import { View, Text, StyleSheet, Button, FlatList, Alert } from 'react-native';
import { fetchWithAuth } from '../lib/api';

export default function ProviderDetail({ route, navigation }) {
  const { providerId } = route.params || {};
  const [provider, setProvider] = useState(null);
  const [error, setError] = useState(false);

  useEffect(() => {
    const loadProvider = async () => {
      try {
        const res = await fetchWithAuth(`/api/providers/${providerId}`);
        const json = await res.json();
        setProvider(json);
      } catch (e) {
        setError(true);
      }
    };
    loadProvider();
  }, [providerId]);

  if (error) return <Text>Tarjoajaa ei löydy.</Text>;
  if (!provider) return <Text>Ladataan...</Text>;

  return (
    <View style={styles.container}>
      <Text style={styles.name}>{provider.name}</Text>
      <Text style={styles.description}>{provider.description}</Text>
      <Button
        title="Arvostelut"
        onPress={() => navigation.navigate('ReviewScreen', { targetType: 'provider', targetId: provider.id, targetName: provider.name })}
      />
      <Text style={styles.section}>Arvostelut</Text>
      <FlatList
        data={provider.reviews || []}
        keyExtractor={(item) => item.id}
        ListEmptyComponent={<Text>Ei arvosteluja vielä.</Text>}
        renderItem={({ item }) => (
          <View style={styles.card}>
            <Text style={styles.reviewer}>{item.reviewer}</Text>
            <Text style={styles.rating}>Arvio: {item.rating}/5</Text>
            <Text>{item.comment}</Text>
          </View>
        )}
      />
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1, padding: 16 },
  name: { fontSize: 20, fontWeight: '700', marginBottom: 8 },
  description: { marginBottom: 16, color: '#444' },
  section: { fontSize: 16, fontWeight: '700', marginTop: 16, marginBottom: 8 },
  card: { padding: 12, borderWidth: 1, borderColor: '#eee', borderRadius: 8, marginBottom: 12 },
  reviewer: { fontWeight: '700', marginBottom: 4 },
  rating: { marginBottom: 6 }
});
